const safeParse=(s,fallback)=>{try{return JSON.parse(s)||fallback}catch{return fallback}};
const store={get(n){if(n==='Notifications')return safeParse(localStorage.getItem('smarttrans_notifications'),[]).map(x=>({'Notification ID':x.id,Message:x.text,Type:x.type||'info',Created:x.createdAt||'', 'Read status':x.read?'Read':'Unread',Owner:x.owner||'',id:x.id}));return safeParse(localStorage.getItem(key(n)),[])},set(n,v){if(n==='Notifications'){localStorage.setItem('smarttrans_notifications',JSON.stringify(v.map(x=>({id:x.id||x['Notification ID']||crypto.randomUUID(),text:x.Message||x.text,type:x.Type||x.type,createdAt:x.Created||x.createdAt,read:/read/i.test(x['Read status']||''),owner:x.Owner||''}))));return}localStorage.setItem(key(n),JSON.stringify(v))}};
const SESSION_KEY='smarttrans_session_v2',USERS_KEY='smarttrans_users_v2';
const demoUsers=[{id:'USR-ADMIN-001',name:'SmartTrans Administrator',email:'admin@smarttrans.com',password:'Admin@123',role:'Admin'},{id:'USR-MANAGER-001',name:'Operations Manager',email:'manager@smarttrans.com',password:'Manager@123',role:'Manager'},{id:'USR-DRIVER-001',name:'Arun K.',email:'driver@smarttrans.com',password:'Driver@123',role:'Driver'},{id:'USR-CUSTOMER-001',name:'Demo Customer',email:'customer@smarttrans.com',password:'Customer@123',role:'Customer'}];
function users(){return safeParse(localStorage.getItem(USERS_KEY),[])}
function activeUser(){const ses=safeParse(sessionStorage.getItem(SESSION_KEY),null);return ses?users().find(u=>u.id===ses.userId)||null:null}
function seedUsers(){let u=users();for(const d of demoUsers)if(!u.some(x=>x.email===d.email))u.push(d);localStorage.setItem(USERS_KEY,JSON.stringify(u))}
function canOpen(n,role){if(!role)return false;if(role==='Admin')return true;if(role==='Manager')return !['Multi-company Management','Login Security Dashboard','Advanced User Profile','Customers'].includes(n);if(role==='Driver')return ['Overview','Shipment Management','Shipment Tracking','Trip Management System','Driver Attendance and Shift Management','Driver Safety Management','Proof of Delivery','Notifications','Advanced User Profile','Interactive Command Center'].includes(n);if(role==='Customer')return ['Overview','Shipment Management','Shipment Tracking','Customer Address Book','Customer Communication Center','Support Tickets','Payment Management','Advanced User Profile','Interactive Command Center','Notifications'].includes(n);return false}
function publicRender(page='home',message=''){document.getElementById('sidebar').style.display='none';document.querySelector('.main').style.display='none';document.getElementById('assistantFab').style.display='none';const root=document.getElementById('publicRoot');root.style.display='block';if(page==='login'||page==='register'||page==='forgot'){root.innerHTML=authMarkup(page,message);bindAuth(page);return}root.innerHTML=`<div class="public-site"><nav class="public-nav"><a class="public-brand" href="#home"><span class="brand-mark">S</span>SmartTrans</a><div class="public-links"><a data-public="home">Home</a><a href="#about">About</a><a href="#services">Services</a><a href="#features">Features</a><a href="#tracking">Tracking</a><a href="#contact">Contact</a></div><div class="public-actions"><button class="button" data-auth="login">Login</button><button class="button primary" data-auth="register">Get started</button></div></nav><section class="hero"><div class="hero-copy"><span class="hero-tag">✦ &nbsp; SMARTER OPERATIONS START HERE</span><h1>Intelligent Transportation.<br><em>Smarter Logistics.</em><br>Faster Deliveries.</h1><p>Bring your fleet, drivers, shipments and customer experience together in one clear operations platform.</p><div class="hero-buttons"><button class="button primary" data-auth="register">Start your demo →</button><button class="button" data-auth="login">Sign in to workspace</button></div><form id="publicTrack" class="hero-tracking"><input id="publicTrackId" placeholder="Enter a tracking ID, e.g. ST-849301"><button>Track shipment</button></form><div id="publicTrackResult"></div></div></section><div class="public-stats"><div class="public-stat"><b>2.8k+</b><span>Shipments managed</span></div><div class="public-stat"><b>96.4%</b><span>On-time performance</span></div><div class="public-stat"><b>31</b><span>Fleet vehicles</span></div><div class="public-stat"><b>24/7</b><span>Operations visibility</span></div></div><section class="public-section" id="about"><span class="eyebrow">ONE CONNECTED PLATFORM</span><h2>Logistics, in clear view.</h2><p>SmartTrans gives teams the tools to plan movement, manage delivery operations, and respond with context. Use this local demo to explore the workflows with sample records.</p><div class="public-cards" id="services">${[['⇄','Fleet & trips','Coordinate vehicles, drivers, routes and last-mile delivery.'],['▤','Shipment visibility','Follow shipment milestones and customer delivery activity.'],['◉','Operational intelligence','Explore performance trends, capacity, service and maintenance.']].map(x=>`<article class="public-card"><i>${x[0]}</i><h3>${x[1]}</h3><p>${x[2]}</p></article>`).join('')}</div></section><section class="public-section" id="features"><span class="eyebrow">BUILT FOR THE FULL JOURNEY</span><h2>From first mile to final mile.</h2><p>Discover tools for transportation, warehousing, returns, supplier workflows, safety, analytics and customer support.</p></section><section class="public-section" id="tracking"><span class="eyebrow">SHIPMENT TRACKING</span><h2>Know where every delivery stands.</h2><form id="publicTrack2" class="hero-tracking"><input id="publicTrackId2" placeholder="Enter tracking ID"><button>Track shipment</button></form><div id="publicTrackResult"></div></section><section class="public-section" id="contact"><span class="eyebrow">CONTACT</span><h2>Let’s move logistics forward.</h2><p>This demonstration runs locally in your browser. For production services, connect a backend and authorized external providers.</p><button class="button primary" data-auth="register">Explore the demo</button></section><footer class="public-footer">© 2026 SmartTrans · Frontend demonstration · Browser storage is not a secure production database.</footer></div>`;root.querySelectorAll('[data-auth]').forEach(b=>b.onclick=()=>publicRender(b.dataset.auth));root.querySelectorAll('[data-public]').forEach(b=>b.onclick=()=>publicRender('home'));document.getElementById('publicTrack').onsubmit=e=>{e.preventDefault();trackPublic(document.getElementById('publicTrackId').value)};document.getElementById('publicTrack2').onsubmit=e=>{e.preventDefault();trackPublic(document.getElementById('publicTrackId2').value)}}
function authMarkup(page,msg){const register=page==='register';return `<div class="auth-shell"><aside class="auth-aside"><a class="public-brand" href="#" data-auth="home"><span class="brand-mark">S</span>SmartTrans</a><h2>${register?'Build a smoother delivery experience.':'Your operations, connected.'}</h2><p>Manage shipments, coordinate teams, and keep every delivery moving with SmartTrans.</p><div class="demo-box"><b>DEMO ACCOUNTS · FOR EVALUATION</b><code>Admin · admin@smarttrans.com / Admin@123<br>Manager · manager@smarttrans.com / Manager@123<br>Driver · driver@smarttrans.com / Driver@123<br>Customer · customer@smarttrans.com / Customer@123</code></div></aside><main class="auth-main"><section class="auth-card"><a class="public-brand" href="#" data-auth="home"><span class="brand-mark">S</span>SmartTrans</a><h1>${register?'Create your demo account':page==='forgot'?'Reset demo password':'Welcome back'}</h1><p>${register?'Register as a customer or driver to explore the platform.':page==='forgot'?'Password reset is unavailable in this local demo.':'Sign in to your logistics workspace.'}</p>${msg?`<div class="${msg.startsWith('Success')?'auth-success':'auth-error'}">${msg.replace(/^Success:?\s*/, '')}</div>`:''}${page==='forgot'?`<div class="notice">Ask your demo administrator to reset an account. Password recovery requires a server-side identity service in production.</div><button class="button primary" data-auth="login">Back to login</button>`:`<form id="authForm">${register?`<div class="field"><label>Full name *</label><input name="name" required minlength="2"></div>`:''}<div class="field"><label>Email address *</label><input name="email" type="email" required autocomplete="email"></div>${register?`<div class="field"><label>Phone number *</label><input name="phone" type="tel" required pattern="[+0-9() .-]{7,20}"></div><div class="field"><label>Account type *</label><select name="role"><option value="Customer">Customer</option><option value="Driver">Driver</option></select></div>`:''}<div class="field"><label>Password *</label><div class="fields-inline"><input style="flex:1" name="password" type="password" required ${register?'minlength="8"':''} autocomplete="${register?'new-password':'current-password'}"><label class="panel-subtitle"><input type="checkbox" data-showpass> Show</label></div></div>${register?`<div class="field"><label>Confirm password *</label><input name="confirm" type="password" required minlength="8"></div>`:`<label class="panel-subtitle"><input name="remember" type="checkbox"> Remember me in this tab</label><button type="button" class="text-btn" data-auth="forgot" style="float:right">Forgot password?</button>`}<div id="authMessage"></div><button class="button primary" style="width:100%;margin-top:17px">${register?'Create account':'Sign in'}</button></form>`}<p style="margin-top:17px">${register?'Already have an account?':'New to SmartTrans?'} <button class="text-btn" data-auth="${register?'login':'register'}">${register?'Sign in':'Create account'}</button></p><small style="color:#9aa5b2;font-size:9px">Demo only. Do not use real passwords or personal information.</small></section></main></div>`}
function bindAuth(page){document.querySelectorAll('[data-auth]').forEach(b=>b.onclick=()=>publicRender(b.dataset.auth));const form=document.getElementById('authForm');if(!form)return;document.querySelector('[data-showpass]')?.addEventListener('change',e=>form.elements.password.type=e.target.checked?'text':'password');form.onsubmit=e=>{e.preventDefault();const d=Object.fromEntries(new FormData(form));const out=document.getElementById('authMessage');if(page==='register'){if(d.password!==d.confirm){out.innerHTML='<div class="auth-error">Passwords do not match.</div>';return}if(!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(d.email)){out.innerHTML='<div class="auth-error">Enter a valid email address.</div>';return}if(!/^\+?[0-9() .-]{7,20}$/.test(d.phone)){out.innerHTML='<div class="auth-error">Enter a valid phone number.</div>';return}let all=users();if(all.some(u=>u.email.toLowerCase()===d.email.toLowerCase())){out.innerHTML='<div class="auth-error">An account with this email already exists.</div>';return}const u={id:'USR-'+crypto.randomUUID(),name:d.name.trim(),email:d.email.trim().toLowerCase(),password:d.password,phone:d.phone,role:['Customer','Driver'].includes(d.role)?d.role:'Customer',createdAt:new Date().toISOString()};all.push(u);localStorage.setItem(USERS_KEY,JSON.stringify(all));if(u.role==='Customer')store.set('Customers',[{ 'Customer ID':'CUS-'+crypto.randomUUID().slice(0,8),'Full name':u.name,Email:u.email,Phone:u.phone,'Account status':'Active',id:crypto.randomUUID()},...store.get('Customers')]);if(u.role==='Driver')store.set('Driver Management',[{'Driver ID':'DRV-'+crypto.randomUUID().slice(0,8),'Full name':u.name,Email:u.email,Phone:u.phone,'License number':'','License expiry':'','Assigned vehicle':'','Availability':'Available',id:crypto.randomUUID()},...store.get('Driver Management')]);activity('Account registered',u.email);publicRender('login','Success: Account created. Sign in to continue.');return}const u=users().find(x=>x.email.toLowerCase()===d.email.trim().toLowerCase()&&x.password===d.password);if(!u){activity('Login failed',d.email);out.innerHTML='<div class="auth-error">Email or password is incorrect.</div>';return}sessionStorage.setItem(SESSION_KEY,JSON.stringify({userId:u.id,role:u.role,startedAt:Date.now(),remember:form.elements.remember?.checked||false}));activity('Login succeeded',u.email);current='Overview';document.getElementById('publicRoot').style.display='none';document.getElementById('sidebar').style.display='flex';document.querySelector('.main').style.display='block';document.getElementById('assistantFab').style.display='grid';seedUsers();initSamples();scheduleSession();navRender();render();toast(`Welcome, ${u.name.split(' ')[0]}`)}}
function scheduleSession(){clearTimeout(window._sessionTimeout);if(!activeUser())return;const mins=+(sessionStorage.getItem('smarttrans_timeout')||30);window._sessionTimeout=setTimeout(()=>{alert('Demo session expired due to inactivity.');signOut()},mins*60000)}
function signOut(){const u=activeUser();if(u)activity('Logged out',u.email);sessionStorage.removeItem(SESSION_KEY);clearTimeout(window._sessionTimeout);current='Overview';publicRender('home')}
function trackPublic(id){const root=document.getElementById('publicTrackResult')||document.querySelector('#publicTrack')?.parentElement;const s=store.get('Shipment Management').find(x=>x['Tracking ID']?.toLowerCase()===String(id||'').trim().toLowerCase());if(!root)return;if(!s){root.innerHTML='<div class="auth-error">No shipment found for that tracking ID.</div>';return}const states=['Order Placed','Confirmed','Picked Up','In Transit','Out for Delivery','Delivered'],st=s.Status||'Order Placed',idx=Math.max(0,states.findIndex(x=>x.toLowerCase()===st.toLowerCase()));root.innerHTML=`<div class="panel tracking-card tracking-result"><b>${s['Tracking ID']}</b> <span class="status">${st}</span><div class="settings-row"><span>Pickup → Destination</span><b>${s['Pickup address']} → ${s['Destination address']}</b></div><div class="settings-row"><span>Expected delivery</span><b>${s['Expected delivery']||'Not scheduled'}</b></div><div class="tracking-timeline">${states.map((x,i)=>`<div class="tracking-step ${i<=idx?'done':''}"><i>${i<idx?'✓':i+1}</i>${x}</div>`).join('')}</div></div>`}
function showTrackingResult(id,target){const root=document.getElementById(target);if(!root)return;const s=recordsFor('Shipment Management').find(x=>x['Tracking ID']?.toLowerCase()===String(id||'').trim().toLowerCase());if(!s){root.innerHTML='<div class="notice">No shipment found in records available to this account.</div>';return}const states=['Order Placed','Confirmed','Picked Up','In Transit','Out for Delivery','Delivered'],idx=Math.max(0,states.findIndex(x=>x.toLowerCase()===String(s.Status).toLowerCase()));root.innerHTML=`<div class="panel tracking-result"><b>${s['Tracking ID']}</b> · ${s.Status}<div class="settings-row"><span>Pickup</span><b>${s['Pickup address']}</b></div><div class="settings-row"><span>Destination</span><b>${s['Destination address']}</b></div><div class="settings-row"><span>Driver</span><b>${s['Assigned driver']||'Unassigned'}</b></div><div class="tracking-timeline">${states.map((x,i)=>`<div class="tracking-step ${i<=idx?'done':''}"><i>${i<idx?'✓':i+1}</i>${x}</div>`).join('')}</div></div>`}
function recordAttendance(action){const u=activeUser(),now=new Date().toISOString(),rows=store.get('Driver Attendance and Shift Management'),today=new Date().toISOString().slice(0,10);if(action==='Check-in'){rows.unshift({Driver:u.name,Shift:'Day shift', 'Check-in':now,'Check-out':'','Working hours':'0','Availability':'On duty','Leave status':'None',id:crypto.randomUUID()});store.set('Driver Attendance and Shift Management',rows);activity('Driver checked in',u.email)}else{const row=rows.find(x=>x.Driver===u.name&&String(x['Check-in']).startsWith(today)&&!x['Check-out']);if(!row){toast('No open check-in found for today');return}row['Check-out']=now;row['Working hours']=((new Date(now)-new Date(row['Check-in']))/36e5).toFixed(2);store.set('Driver Attendance and Shift Management',rows);activity('Driver checked out',u.email)}render();toast(`${action} saved`)}
function setupSignature(){const c=document.getElementById('signaturePad');if(!c)return;const ctx=c.getContext('2d');ctx.lineWidth=2;ctx.lineCap='round';ctx.strokeStyle='#172033';let drawing=false;c.onpointerdown=e=>{drawing=true;c.setPointerCapture(e.pointerId);const r=c.getBoundingClientRect();ctx.beginPath();ctx.moveTo((e.clientX-r.left)*c.width/r.width,(e.clientY-r.top)*c.height/r.height)};c.onpointermove=e=>{if(!drawing)return;const r=c.getBoundingClientRect();ctx.lineTo((e.clientX-r.left)*c.width/r.width,(e.clientY-r.top)*c.height/r.height);ctx.stroke()};c.onpointerup=()=>drawing=false;c.onpointercancel=()=>drawing=false;document.getElementById('clearSignature')?.addEventListener('click',()=>ctx.clearRect(0,0,c.width,c.height))}
function saveProof(){const tracking=document.getElementById('podTracking')?.value.trim(),receiver=document.getElementById('podName')?.value.trim(),u=activeUser(),ship=store.get('Shipment Management').find(x=>x['Tracking ID']===tracking);if(!ship||!receiver){toast('Enter a valid tracking ID and receiver name');return}if(u.role==='Driver'&&ship['Assigned driver']!==u.name){toast('This delivery is not assigned to you');return}ship.Status='Delivered';ship['Delivered at']=new Date().toISOString();store.set('Shipment Management',store.get('Shipment Management').map(x=>x.id===ship.id?ship:x));const history=safeParse(localStorage.getItem('smarttrans_deliveryHistory'),[]);history.unshift({id:crypto.randomUUID(),tracking,receiver,deliveredAt:ship['Delivered at'],by:u.email,signature:document.getElementById('signaturePad')?.toDataURL()||''});localStorage.setItem('smarttrans_deliveryHistory',JSON.stringify(history));notify(`Shipment ${tracking} delivered`,'success');activity('Delivery completed',tracking);render();toast('Proof of delivery saved')}
function markNotificationsRead(){const visible=recordsFor('Notifications').map(x=>x.id);const all=store.get('Notifications').map(x=>visible.includes(x.id)?{...x,'Read status':'Read'}:x);store.set('Notifications',all)}function clearNotifications(){const visible=recordsFor('Notifications').map(x=>x.id);store.set('Notifications',store.get('Notifications').filter(x=>!visible.includes(x.id)))}
function showNotifications(){const list=recordsFor('Notifications');if(!list.length){alert('No notifications');return}alert(list.slice(0,12).map(n=>`${n['Read status']==='Unread'?'●':'○'} ${n.Message}`).join('\n'));markNotificationsRead()}
function assistantAnswer(q){q=String(q||'').trim();if(!q)return;const box=document.getElementById('assistantMessages');const add=(text,cls='')=>{const d=document.createElement('div');d.className='assistant-bubble '+cls;d.textContent=text;box.append(d)};add(q,'user');const u=activeUser(),ship=recordsFor('Shipment Management'),vehicles=recordsFor('Vehicle Management'),drivers=recordsFor('Driver Management'),lc=q.toLowerCase();let ans;if(/how many.*vehicles|available vehicles/.test(lc))ans=`There are ${vehicles.filter(v=>/available/i.test(v.Status||'')).length} available vehicles in the records visible to your ${u.role.toLowerCase()} account.`;else if(/driver/.test(lc)&&/available/.test(lc))ans=`${drivers.filter(d=>/available/i.test(d.Availability||'')).length} drivers are marked available in your accessible records.`;else if(/maintenance|service due/.test(lc)){const due=recordsFor('Maintenance Management').filter(x=>x['Next service date']&&new Date(x['Next service date'])<new Date(Date.now()+30*864e5));ans=due.length?`Maintenance due soon: ${due.map(x=>x['Vehicle ID']).join(', ')}.`:'No maintenance records due within 30 days.'}else if(/completed|delivered/.test(lc))ans=`${ship.filter(s=>/delivered/i.test(s.Status||'')).length} deliveries are marked completed in the records visible to you.`;else if(/shipment|status|tracking/.test(lc)){const id=q.match(/\bST-[A-Z0-9-]+\b/i)?.[0];if(id){const s=ship.find(x=>x['Tracking ID']?.toLowerCase()===id.toLowerCase());ans=s?`Shipment ${id} is ${s.Status}, from ${s['Pickup address']} to ${s['Destination address']}.`:`I couldn't find ${id} in the records available to your account.`}else ans=`You have ${ship.filter(s=>!/delivered|cancelled/i.test(s.Status||'')).length} active and ${ship.filter(s=>/delivered/i.test(s.Status||'')).length} completed shipment records available.`}else ans='I can answer about available vehicles, drivers, shipment status, completed deliveries, and maintenance using your accessible demo records.';add(ans);box.scrollTop=box.scrollHeight}
function activity(action,detail=''){const a=safeParse(localStorage.getItem('smarttrans_activity'),[]);a.unshift({id:crypto.randomUUID(),action,detail,at:new Date().toISOString(),user:activeUser()?.email||'system'});localStorage.setItem('smarttrans_activity',JSON.stringify(a.slice(0,500)))}
function notify(message,type='info'){const a=safeParse(localStorage.getItem('smarttrans_notifications'),[]);a.unshift({id:crypto.randomUUID(),text:message,type,createdAt:new Date().toISOString(),read:false,owner:activeUser()?.email||''});localStorage.setItem('smarttrans_notifications',JSON.stringify(a.slice(0,200)))}
function recordsFor(n){const u=activeUser();if(!u)return[];let all=store.get(n);if(n==='Shipment Tracking')all=store.get('Shipment Management').map(s=>({'Tracking ID':s['Tracking ID'],'Shipment ID':s['Shipment ID'],'Pickup address':s['Pickup address'],'Destination address':s['Destination address'],'Booking date':s['Booking date'],'Expected delivery':s['Expected delivery'],'Current status':s.Status,'Progress':`${Math.max(0,['Order Placed','Confirmed','Picked Up','In Transit','Out for Delivery','Delivered'].findIndex(x=>x.toLowerCase()===String(s.Status).toLowerCase()))*20}%`,id:s.id}));if(n==='Notifications')return u.role==='Admin'||u.role==='Manager'?all:all.filter(x=>x.Owner===u.email);if(n==='Advanced Notification Rules'&&u.role!=='Admin'&&u.role!=='Manager')return[];if(u.role==='Admin'||u.role==='Manager')return all;if(n==='Trip Management System'&&u.role==='Driver')return all.filter(t=>t.Driver===u.name||t['Assigned driver']===u.name);if(n==='Driver Attendance and Shift Management'&&u.role==='Driver')return all.filter(t=>t.Driver===u.name);if(n==='Customer Address Book'&&u.role==='Customer')return all.filter(a=>a.ownerEmail===u.email);if(n==='Shipment Management'||n==='Shipment Tracking'){if(u.role==='Customer')return all.filter(s=>s['Sender email']===u.email);if(u.role==='Driver')return all.filter(s=>s['Assigned driver']===u.name||s['Assigned driver']===u.id)}if(n==='Payment Management'&&u.role==='Customer')return all.filter(p=>p['Customer email']===u.email);if(n==='Support Tickets'&&u.role==='Customer')return all.filter(t=>t['Customer email']===u.email);if(n==='Driver Management'&&u.role==='Driver')return all.filter(d=>d.Email===u.email);return[]}
