function initSamples(){for(const [n,rows] of Object.entries(sampleRows)){if(!store.get(n).length)store.set(n,rows.map((r,i)=>({id:crypto.randomUUID(),...Object.fromEntries(fieldsFor(n).map((f,j)=>[f,r[j]??''])),createdAt:new Date().toISOString()})))}if(!localStorage.getItem('smarttrans_notifications'))localStorage.setItem('smarttrans_notifications',JSON.stringify([{text:'VH-096 maintenance due in 2 days',type:'warning'},{text:'Trip TRP-24081 is on schedule',type:'info'}]))}
initSamples();
const content=document.getElementById('content');let current='Overview',charts=[];
function navRender(){const nav=document.getElementById('nav'),role=activeUser()?.role;nav.innerHTML=groups.map(g=>{let items=g.items.filter(n=>canOpen(n,role));return items.length?`<div class="nav-group"><div class="nav-label">${g.name}</div>${items.map(n=>{const ix=featureNames.indexOf(n);return`<a class="nav-item ${current===n?'active':''}" data-nav="${n}"><span class="nav-ico">${g.icon}</span>${n}${ix>=0?`<span class="nav-badge">${53+ix}</span>`:''}</a>`}).join('')}</div>`:''}).join('');nav.querySelectorAll('[data-nav]').forEach(a=>a.onclick=()=>go(a.dataset.nav))}
function go(n){if(!activeUser()){publicRender('login');return}if(!canOpen(n,activeUser().role)){toast('Your demo role does not have access to that area');return}current=n;document.getElementById('pageCrumb').textContent=n;navRender();document.querySelector('.sidebar').classList.remove('open');render()}
function heading(n,sub,action=true){return `<div class="page-title-row"><div><span class="eyebrow">SMARTTRANS / OPERATIONS</span><h1 class="page-title">${n}</h1><p class="page-subtitle">${sub}</p></div><div class="actions">${action?`<button class="button" data-export>Export</button><button class="button primary" data-create>＋ New ${singular(n)}</button>`:''}</div></div>`}
function singular(n){return ({'Supplier Management':'supplier','Purchase Order Management':'purchase order','Trip Management System':'trip','Delivery Zone Management':'zone','Customer Address Book':'address','Advanced Notification Rules':'notification rule','Logistics Automation Rules':'automation rule','Driver Attendance and Shift Management':'shift'}[n]||n.replace(/ Management| Dashboard| Center| System| Operations/g,'').toLowerCase().replace(/s$/,''))}
function metric(label,value,foot,icon='◉',trend='positive'){return `<div class="metric-card"><div class="metric-head">${label}<span class="metric-icon">${icon}</span></div><div class="metric-value">${value}</div><div class="metric-foot"><span class="${trend}">${foot.split('|')[0]}</span>${foot.includes('|')?foot.split('|')[1]:''}</div></div>`}
function panel(title,sub,body,extra=''){return `<section class="panel"><div class="panel-head"><div><h3 class="panel-title">${title}</h3>${sub?`<div class="panel-subtitle">${sub}</div>`:''}</div>${extra}</div>${body}</section>`}
function statusClass(v){v=String(v||'').toLowerCase();if(/fail|violat|overdue|high|maintenance|rejected|breakdown|critical|delayed/.test(v))return'bad';if(/pending|scheduled|review|medium|redelivery|receiving|due/.test(v))return'warn';if(/idle|available|complete|approved|on time|verified|low|in progress|current|active/.test(v))return'';return'neutral'}
function table(n,rows,limit=50,actions=true){const f=fieldsFor(n);if(!rows.length)return`<div class="empty"><strong>No ${singular(n)} records yet</strong>Create your first record to start tracking this workflow.</div>`;return`<div class="table-scroll"><table class="data-table"><thead><tr>${f.map(x=>`<th>${x}</th>`).join('')}${actions?'<th></th>':''}</tr></thead><tbody>${rows.slice(0,limit).map(r=>`<tr>${f.map(x=>{let v=r[x]??'—';return`<td>${x.toLowerCase().includes('status')||/risk|compliance|availability|verified|performance|demand|condition|suitability/i.test(x)?`<span class="status ${statusClass(v)}">${v}</span>`:v}</td>`}).join('')}${actions?`<td><div class="row-actions"><button class="text-btn" data-edit="${r.id}">Edit</button><button class="text-btn" data-delete="${r.id}">Delete</button></div></td>`:''}</tr>`).join('')}</tbody></table></div>`}
function bindTable(n){document.querySelector('#tableSearch')?.addEventListener('input',e=>{const val=e.target.value.toLowerCase(),body=document.querySelector('#dataRows');if(body)body.innerHTML=table(n,recordsFor(n).filter(r=>Object.values(r).join(' ').toLowerCase().includes(val)));bindRows(n)})}
function bindRows(n){document.querySelectorAll('[data-edit]').forEach(b=>b.onclick=()=>openForm(n,b.dataset.edit));document.querySelectorAll('[data-delete]').forEach(b=>b.onclick=()=>removeRecord(n,b.dataset.delete))}
function modulePage(n){const rows=recordsFor(n),sub=`Manage ${n.toLowerCase()} in your demo workspace. Changes are saved in this browser.`;let stats=moduleStats(n,rows);let extra='';if(n==='Traffic Management Dashboard'||n==='Advanced Fleet Intelligence'||n==='Geofencing Simulator'||n==='Route Deviation Alerts'||n==='Vehicle Theft and Security Alerts'||n==='Delivery Zone Management'||n==='Real-time Operations Control Center')extra=mapPanel(n);
 let tools=n==='Bulk Shipment Import'?`<label class="button" for="csvFile">Import CSV</label><input type="file" id="csvFile" accept=".csv,text/csv" hidden><button class="button" id="downloadTemplate">CSV template</button>`:'';
 let workflow=workflowPanel(n,rows);
 let dataPanel=panel(n,'Record management · browser-local demo',`<div class="table-tools" style="margin-bottom:10px"><input class="filter-input" id="tableSearch" placeholder="Filter records…"><span class="panel-subtitle">${rows.length} records</span></div><div id="dataRows">${table(n,rows,50,!['Shipment Tracking','Notifications'].includes(n))}</div>`);
 let toolbar=`<div class="actions" style="justify-content:flex-end;margin-top:-12px;margin-bottom:16px">${tools}${['Shipment Tracking','Notifications'].includes(n)?'':`<button class="button" data-export>Export CSV</button><button class="button primary" data-create>＋ New ${singular(n)}</button>`}</div>`;
 return heading(n,sub,false)+toolbar+`${stats?`<div class="metric-grid">${stats}</div>`:''}${workflow}${extra}${dataPanel}`}
function moduleStats(n,rows){const map={'Advanced Fleet Intelligence':[['Fleet health','94 / 100','+2.4%|vs last month','◉'],['Utilization','76.8%','+4.2%|vs last week','↗'],['On the road','24 / 31','78%|available fleet','⇄'],['Idle vehicles','4','−2|since yesterday','◷']], 'Trip Management System':[['Active trips','12','+3|today','⇄'],['Scheduled','28','+8%|vs yesterday','◷'],['Completed today','46','+12%|vs yesterday','✓'],['On-time arrival','94.2%','+1.8%|this month','⌖']], 'Delivery Failure Analytics':[['Failed deliveries','18','−12%|vs last week','!'],['Failure rate','3.8%','−0.6%|this month','↘'],['Redelivery queue','7','3|due today','↻'],['Top reason','Unavailable','42%|of failed stops','◎']], 'SLA Management':[['SLA compliance','96.4%','+1.2%|this month','✓'],['At risk','9','3|due within 1 hour','◷'],['Violations','14','−8%|vs last month','!'],['Avg. delay','18 min','−4 min|vs last month','↘']], 'Delivery Capacity Planning':[['Daily capacity','420','72%|committed','▦'],['Vehicles available','18','of 31|fleet total','▣'],['Drivers available','22','of 28|on roster','♙'],['Pending shipments','136','32%|of daily capacity','▤']], 'Predictive Maintenance Dashboard':[['Healthy vehicles','27 / 31','87%|fleet health','✓'],['Service due soon','4','2|within 7 days','◷'],['High maintenance risk','2','Schedule inspection|','!'],['Avg. health score','89','+3|vs last month','◉']], 'Return and Reverse Logistics':[['Return requests','26','+4|this week','↩'],['Awaiting pickup','8','2|scheduled today','◷'],['Refund pending','11','₹24,800|total value','₹'],['Return rate','2.1%','−0.3%|this month','↘']]}[n];if(map)return map.map(x=>metric(...x)).join('');if(!rows.length)return'';return [metric('Total records',rows.length,'Updated just now','▤'),metric('In progress',rows.filter(r=>Object.values(r).some(v=>/progress|active|pending|scheduled/i.test(String(v)))).length,'Across active workflow','◷'),metric('Completed / ready',rows.filter(r=>Object.values(r).some(v=>/complete|available|approved|verified/i.test(String(v)))).length,'Ready for next step','✓'),metric('Needs attention',rows.filter(r=>Object.values(r).some(v=>/high|fail|overdue|violation|rejected/i.test(String(v)))).length,'Review flagged records','!','negative')].join('')}
